<?php require '../config.php'; require '../lib.php'; require '../api_lib.php';
if(session_status()===PHP_SESSION_ACTIVE) session_destroy(); header_remove('Set-Cookie');
if(!in_array($_SERVER['REQUEST_METHOD'],['GET','HEAD'],true)) api_err(405,'Read-only API: use GET');
api_auth(); $pdo=db(); $r=trim((string)($_GET['r']??($_SERVER['PATH_INFO']??'')),'/'); $id=(int)($_GET['id']??$_GET['device']??0);
try{
switch($r){
 case '': case 'index': api_json(['name'=>'VM Monitor API','version'=>'v1','app_version'=>VMMON_VERSION,'usage'=>'GET api/v1.php?r=<endpoint> with header "Authorization: Bearer <token>"','endpoints'=>['devices'=>'all devices (filter: category=server|virtualization|network|storage|bmc|services, group=name, up=0|1)','device&id=N'=>'one device with checks, interfaces and VMs','checks'=>'all checks (filter: device=ID, up=0|1)','interfaces'=>'network interfaces (filter: device=ID)','alerts'=>'currently firing alerts','rules'=>'alert rules','events'=>'alert history (filter: since, until, open=1, limit)','alert_log'=>'sent notifications (filter: since, limit)','series'=>'history: metric=cpu|memory|disk|net_in|net_out|net_errors|net_discards|check_ms|check_uptime, device=ID, interface=INDEX, disk=NAME, check=ID, from, to, step, format=grafana','metrics'=>'Prometheus text format (scrape target)']]);
 case 'devices': { $cks=api_checks_by_server(); $g=api_groups_map(); $o=[]; $cat=(string)($_GET['category']??''); $gr=(string)($_GET['group']??''); $uf=$_GET['up']??null;
  foreach(api_servers() as $s){ $d=api_device($s,$cks[$s['id']]??[],$g[$s['id']]??[]); if($cat!==''&&$d['category']!==$cat) continue; if($gr!==''&&!in_array($gr,$d['groups'],true)) continue; if($uf!==null&&$uf!==''&&$d['up']!==((int)$uf===1)) continue; $o[]=$d; }
  api_json(['count'=>count($o),'devices'=>$o]); }
 case 'device': { if(!$id) api_err(400,'id required'); $s=api_servers($id)[0]??null; if(!$s) api_err(404,'device not found'); $cks=api_checks_by_server(); $g=api_groups_map(); $d=api_device($s,$cks[$id]??[],$g[$id]??[]);
  $d['checks']=array_map(fn($c)=>api_check_row($c,$s),$cks[$id]??[]); $q=$pdo->prepare('SELECT * FROM net_if WHERE server_id=? ORDER BY if_index'); $q->execute([$id]); $d['interfaces']=array_map(fn($i)=>api_iface_row($i,$s),$q->fetchAll());
  if(dev_cat($s)==='hv'){ $hd=json_decode((string)$s['hv_data'],true)?:[]; $d['vms']=array_map(fn($v)=>['name'=>$v['n'],'state'=>$v['state']??null,'node'=>$v['node']??null,'cpu_pct'=>isset($v['cpu'])?round((float)$v['cpu'],1):null,'memory_pct'=>(($v['mem_t']??0)>0&&isset($v['mem']))?round($v['mem']/$v['mem_t']*100,1):null],$hd['vms']??[]); }
  api_json($d); }
 case 'checks': { $sn=[]; foreach(api_servers() as $s) $sn[$s['id']]=$s; $o=[]; $uf=$_GET['up']??null; foreach(api_checks_by_server() as $sid=>$l){ if($id&&$sid!==$id) continue; foreach($l as $c){ $row=api_check_row($c,$sn[$sid]??null); if($uf!==null&&$uf!==''&&$row['up']!==((int)$uf===1)) continue; $o[]=$row; } } api_json(['count'=>count($o),'checks'=>$o]); }
 case 'interfaces': { $sn=[]; foreach(api_servers() as $s) $sn[$s['id']]=$s; $q=$pdo->prepare('SELECT * FROM net_if'.($id?' WHERE server_id=?':'').' ORDER BY server_id,if_index'); $q->execute($id?[$id]:[]); $o=array_map(fn($i)=>api_iface_row($i,$sn[$i['server_id']]??null),$q->fetchAll()); api_json(['count'=>count($o),'interfaces'=>$o]); }
 case 'alerts': { $o=array_map(fn($f)=>['rule_id'=>(int)$f['rule_id'],'rule'=>metric_label($f['metric']),'metric'=>$f['metric'],'threshold'=>(float)$f['threshold'],'device_id'=>(int)$f['server_id'],'device'=>$f['server'],'since'=>date('c',strtotime($f['since']))],api_firing()); api_json(['count'=>count($o),'alerts'=>$o]); }
 case 'rules': { $o=[]; foreach($pdo->query('SELECT * FROM alert_rules ORDER BY id') as $x) $o[]=['id'=>(int)$x['id'],'metric'=>$x['metric'],'name'=>metric_label($x['metric']),'threshold'=>(float)$x['threshold'],'minutes'=>(int)$x['minutes'],'repeat_min'=>(int)$x['repeat_min'],'enabled'=>(bool)$x['enabled']]; api_json(['count'=>count($o),'rules'=>$o]); }
 case 'events': { $lim=max(1,min(1000,(int)($_GET['limit']??200))); $w=['1']; $p=[]; if(!empty($_GET['since'])){ $w[]='started>=FROM_UNIXTIME(?)'; $p[]=api_time($_GET['since'],0); } if(!empty($_GET['until'])){ $w[]='started<=FROM_UNIXTIME(?)'; $p[]=api_time($_GET['until'],time()); } if(!empty($_GET['open'])) $w[]='ended IS NULL'; if($id){ $w[]='server_id=?'; $p[]=$id; }
  $q=$pdo->prepare('SELECT * FROM alert_events WHERE '.implode(' AND ',$w).' ORDER BY started DESC LIMIT '.$lim); $q->execute($p); $ML=metric_labels();
  $o=array_map(fn($e)=>['id'=>(int)$e['id'],'device_id'=>$e['server_id']===null?null:(int)$e['server_id'],'device'=>$e['server_name'],'kind'=>$e['kind'],'rule'=>$ML[$e['kind']]??$e['kind'],'severity'=>$e['sev'],'detail'=>$e['detail'],'started'=>date('c',strtotime($e['started'])),'ended'=>$e['ended']?date('c',strtotime($e['ended'])):null,'duration_s'=>$e['dur']===null?null:(int)$e['dur'],'notified'=>(bool)$e['notified']],$q->fetchAll()); api_json(['count'=>count($o),'events'=>$o]); }
 case 'alert_log': { $lim=max(1,min(1000,(int)($_GET['limit']??200))); $w=['ts>=FROM_UNIXTIME(?)']; $p=[api_time($_GET['since']??null,time()-86400*7)]; if($id){ $w[]='server_id=?'; $p[]=$id; } $q=$pdo->prepare('SELECT * FROM alert_log WHERE '.implode(' AND ',$w).' ORDER BY id DESC LIMIT '.$lim); $q->execute($p);
  $o=array_map(fn($e)=>['id'=>(int)$e['id'],'time'=>date('c',strtotime($e['ts'])),'device_id'=>$e['server_id']===null?null:(int)$e['server_id'],'device'=>$e['server_name'],'rule'=>metric_label($e['metric']),'metric'=>$e['metric'],'event'=>$e['event'],'message'=>$e['message']],$q->fetchAll()); api_json(['count'=>count($o),'log'=>$o]); }
 case 'metrics': header('Content-Type: text/plain; version=0.0.4; charset=utf-8'); header('Cache-Control: no-store'); echo api_prometheus(); exit;
 case 'series': { $m=(string)($_GET['metric']??''); $to=api_time($_GET['to']??null,time()); $from=api_time($_GET['from']??null,$to-86400); if($from>=$to) api_err(400,'from must be before to'); if($to-$from>86400*400) api_err(400,'range too large (max 400 days)');
  $step=max(300,(int)($_GET['step']??0)); if(!isset($_GET['step'])) $step=max(300,(int)ceil(($to-$from)/1000/300)*300); $step=(int)(ceil($step/300)*300); $lab=['metric'=>$m]; $unit=''; $rows=[];
  $ex=function($sql,$p) use($pdo){ $q=$pdo->prepare($sql); $q->execute($p); return $q->fetchAll(); };
  if(in_array($m,['cpu','memory'],true)){ if(!$id) api_err(400,'device required'); $c=$m==='cpu'?'cpu':'mem'; $unit='percent'; $rows=$ex("SELECT FLOOR(UNIX_TIMESTAMP(bk)/$step)*$step t,SUM({$c}_sum)/NULLIF(SUM({$c}_n),0) v,MAX({$c}_max) mx FROM load_hist WHERE server_id=? AND bk>=FROM_UNIXTIME(?) AND bk<FROM_UNIXTIME(?) GROUP BY t ORDER BY t",[$id,$from,$to]); $lab['device_id']=$id; }
  elseif($m==='disk'){ if(!$id) api_err(400,'device required'); $dk=(string)($_GET['disk']??''); if($dk===''){ $q=$pdo->prepare('SELECT DISTINCT dk FROM disk_hist WHERE server_id=? ORDER BY dk'); $q->execute([$id]); api_json(['error'=>'disk required','message'=>'Specify disk=NAME','disks'=>$q->fetchAll(PDO::FETCH_COLUMN)],400); } $unit='percent'; $rows=$ex("SELECT FLOOR(UNIX_TIMESTAMP(bk)/$step)*$step t,SUM(used_sum)/NULLIF(SUM(n),0) v,MAX(used_max) mx FROM disk_hist WHERE server_id=? AND dk=? AND bk>=FROM_UNIXTIME(?) AND bk<FROM_UNIXTIME(?) GROUP BY t ORDER BY t",[$id,$dk,$from,$to]); $lab+=['device_id'=>$id,'disk'=>$dk]; }
  elseif(in_array($m,['net_in','net_out','net_errors','net_discards'],true)){ if(!$id) api_err(400,'device required'); $ix=$_GET['interface']??''; if($ix===''||!ctype_digit((string)$ix)){ $q=$pdo->prepare('SELECT if_index,name FROM net_if WHERE server_id=? ORDER BY if_index'); $q->execute([$id]); $l=$q->fetchAll(); $f=null; foreach($l as $i) if($ix!==''&&strcasecmp($i['name'],(string)$ix)===0) $f=(int)$i['if_index']; if($f===null) api_json(['error'=>'interface required','message'=>'Specify interface=INDEX (or exact name)','interfaces'=>$l],400); $ix=$f; } $ix=(int)$ix;
   [$a,$b,$unit]=['net_in'=>['in_sum','in_max','bits_per_second'],'net_out'=>['out_sum','out_max','bits_per_second'],'net_errors'=>['err_sum','err_max','per_minute'],'net_discards'=>['disc_sum','disc_max','per_minute']][$m]; $rows=$ex("SELECT FLOOR(UNIX_TIMESTAMP(bk)/$step)*$step t,SUM($a)/NULLIF(SUM(n),0) v,MAX($b) mx FROM net_hist WHERE server_id=? AND if_index=? AND bk>=FROM_UNIXTIME(?) AND bk<FROM_UNIXTIME(?) GROUP BY t ORDER BY t",[$id,$ix,$from,$to]); $lab+=['device_id'=>$id,'interface'=>$ix]; }
  elseif($m==='check_ms'||$m==='check_uptime'){ $cid=(int)($_GET['check']??0); if(!$cid) api_err(400,'check required (check id, see r=checks)'); $lab['check_id']=$cid;
   if($m==='check_ms'){ $unit='ms'; $rows=$ex("SELECT FLOOR(UNIX_TIMESTAMP(bk)/$step)*$step t,SUM(ms_sum)/NULLIF(SUM(n),0) v,MAX(ms_max) mx FROM check_ms_hist WHERE check_id=? AND bk>=FROM_UNIXTIME(?) AND bk<FROM_UNIXTIME(?) GROUP BY t ORDER BY t",[$cid,$from,$to]); }
   else { $step=max(3600,(int)(ceil($step/3600)*3600)); $unit='percent'; $rows=$ex("SELECT FLOOR(UNIX_TIMESTAMP(hr)/$step)*$step t,SUM(up)/NULLIF(SUM(total),0)*100 v,MIN(up/NULLIF(total,0))*100 mx FROM check_hist WHERE check_id=? AND hr>=FROM_UNIXTIME(?) AND hr<FROM_UNIXTIME(?) GROUP BY t ORDER BY t",[$cid,$from,$to]); } }
  else api_err(400,'unknown metric; use cpu|memory|disk|net_in|net_out|net_errors|net_discards|check_ms|check_uptime');
  $nm=$m; foreach($lab as $k=>$v) if($k!=='metric') $nm.=' '.$k.'='.$v;
  if(($_GET['format']??'')==='grafana') api_json([['target'=>$nm,'datapoints'=>array_map(fn($x)=>[$x['v']===null?null:round((float)$x['v'],3),(int)$x['t']*1000],$rows)]]);
  api_json(['metric'=>$m,'unit'=>$unit,'labels'=>$lab,'from'=>date('c',$from),'to'=>date('c',$to),'step_s'=>$step,'points'=>array_map(fn($x)=>['t'=>date('c',(int)$x['t']),'ts'=>(int)$x['t'],'value'=>$x['v']===null?null:round((float)$x['v'],3),'max'=>$x['mx']===null?null:round((float)$x['mx'],3)],$rows)]); }
 default: api_err(404,'unknown endpoint: '.$r);
} }catch(Throwable $e){ applog('error','api','API error: '.$e->getMessage()); api_err(500,'internal error'); }
